import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CZGNF-7T.js";const _=JSON.parse('{"title":"승인 / 반려 / 상신 회수","description":"","frontmatter":{},"headers":[],"relativePath":"approval/action.md","filePath":"approval/action.md","lastUpdated":1787498179000}'),l={name:"approval/action.md"};function n(i,a,s,c,d,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="승인-반려-상신-회수" tabindex="-1">승인 / 반려 / 상신 회수 <a class="header-anchor" href="#승인-반려-상신-회수" aria-label="Permalink to &quot;승인 / 반려 / 상신 회수&quot;">​</a></h1><p>결재 진행 중 발생하는 각 결재 액션의 처리 기준과 절차를 안내합니다.</p><h2 id="_1-결재-승인-approve" tabindex="-1">1. 결재 승인 (Approve) <a class="header-anchor" href="#_1-결재-승인-approve" aria-label="Permalink to &quot;1. 결재 승인 (Approve)&quot;">​</a></h2><p>현재 결재 순번에 해당하는 결재자는 문서의 내용과 첨부파일을 확인한 후 승인할 수 있습니다.</p><ul><li><strong>승인 의견 입력</strong>: 승인 시 필요한 추가 코멘트를 선택적으로 남길 수 있습니다.</li><li><strong>전자 서명 날인</strong>: 승인이 완료되면 문서 타임라인 및 인쇄용 PDF의 결재란에 결재자의 전자 서명/도장 및 승인 일시가 자동으로 각인됩니다.</li><li><strong>다음 단계 호출</strong>: 승인 즉시 다음 순번 결재자에게 모바일 푸시 및 웹 알림이 전달됩니다.</li></ul><h2 id="_2-결재-반려-reject" tabindex="-1">2. 결재 반려 (Reject) <a class="header-anchor" href="#_2-결재-반려-reject" aria-label="Permalink to &quot;2. 결재 반려 (Reject)&quot;">​</a></h2><p>결재 내용의 보완이 필요하거나 부적합한 경우 문서를 반려할 수 있습니다.</p><ul><li><strong>반려 사유 입력 필수</strong>: 결재자는 기안자가 수정·보완할 수 있도록 <strong>반려 사유(의견)를 필수로 입력</strong>해야 합니다.</li><li><strong>결재선 즉시 중단</strong>: 반려 시 후속 결재 단계는 모두 중단되며, 문서 상태가 <code>반려 (rejected)</code>로 전환됩니다.</li><li><strong>기안자 알림</strong>: 기안자에게 반려 사유가 포함된 푸시 알림이 발송되며, 기안자는 문서를 복사하거나 수정하여 재상신할 수 있습니다.</li></ul><h2 id="_3-기안-회수-상신-취소-cancel" tabindex="-1">3. 기안 회수 / 상신 취소 (Cancel) <a class="header-anchor" href="#_3-기안-회수-상신-취소-cancel" aria-label="Permalink to &quot;3. 기안 회수 / 상신 취소 (Cancel)&quot;">​</a></h2><p>기안자가 상신 후 오탈자를 발견했거나 내용 수정이 필요한 경우 상신된 결재를 다시 회수하여 임시저장 상태로 되돌릴 수 있습니다.</p><h3 id="회수-가능-조건" tabindex="-1">회수 가능 조건 <a class="header-anchor" href="#회수-가능-조건" aria-label="Permalink to &quot;회수 가능 조건&quot;">​</a></h3><ul><li><strong>1차 결재자가 승인하기 전</strong>: 기안자는 상세 화면에서 <code>[기안 회수]</code> 버튼을 눌러 언제든지 안전하게 문서를 회수할 수 있습니다.</li><li>회수 시 기존 결재선 단계는 초기화되며, 문서는 <code>임시저장 (draft)</code> 상태로 변경되어 내용을 수정한 후 다시 상신할 수 있습니다.</li></ul><h3 id="회수-불가-조건" tabindex="-1">회수 불가 조건 <a class="header-anchor" href="#회수-불가-조건" aria-label="Permalink to &quot;회수 불가 조건&quot;">​</a></h3><ul><li><strong>1차 결재자가 이미 승인을 완료한 경우</strong>: 결재 프로세스가 이미 시작되었으므로 기안자가 임의로 회수할 수 없으며, 결재자에게 반려를 요청해야 합니다.</li><li><strong>최종 승인이 완료된 경우</strong>: 법적 효력이 발생하고 채번된 문서는 회수할 수 없습니다.</li></ul>',14)])])}const u=e(l,[["render",n]]);export{_ as __pageData,u as default};
